<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { categories, categoryLabels } from '../campus-merchant/workflow-api'
import { config } from '../../campus-shared/config'
import AmapView from './AmapView.vue'
import PaginationBar from '../../campus-shared/PaginationBar.vue'
import * as api from './api'
const categoryOptions = ref<string[]>([])
const longitude = ref(''), latitude = ref(''), radius = ref(5000), category = ref(''), capability = ref<api.Capabilities | null>(null), result = ref<Awaited<ReturnType<typeof api.nearby>> | null>(null), busy = ref(false), message = ref('')
async function locate() { busy.value = true; message.value = ''; try { if (!navigator.geolocation) throw new Error('当前浏览器不支持定位，可手动输入 WGS84 坐标'); const position = await new Promise<GeolocationPosition>((resolve, reject) => navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: config.apiTimeoutMs, maximumAge: 0 })); longitude.value = position.coords.longitude.toFixed(7); latitude.value = position.coords.latitude.toFixed(7); await search() } catch (e) { message.value = e instanceof Error ? e.message : '定位被拒绝或暂不可用，可手动输入坐标' } finally { busy.value = false } }
async function search(page = 1) { if (!longitude.value || !latitude.value) return; busy.value = true; message.value = ''; try { result.value = await api.nearby(longitude.value, latitude.value, radius.value, category.value, page) } catch (e) { result.value = null; message.value = e instanceof Error ? e.message : '附近商家查询失败' } finally { busy.value = false } }
onMounted(async () => { try { capability.value = await api.capabilities(); categoryOptions.value = await categories(); radius.value = Math.min(radius.value, capability.value.maxRadiusMeters) } catch (e) { message.value = e instanceof Error ? e.message : '服务不可用' } })
</script>
<template><section><h1>附近商家</h1><p class="muted">点击后才申请浏览器定位；位置只用于本次查询。距离为直线距离，不代表步行路线。</p><button :disabled="busy" @click="locate">使用当前位置寻找商家</button><form class="workspace-card" @submit.prevent="search()"><h2>按位置查询</h2><p>手动输入须使用 WGS84 坐标，不能直接粘贴高德/腾讯地图的 GCJ02 坐标。</p><div class="trade-fields"><div><label for="nearbyLongitude">WGS84 经度</label><input id="nearbyLongitude" v-model="longitude" type="number" min="-180" max="180" step="any" required /></div><div><label for="nearbyLatitude">WGS84 纬度</label><input id="nearbyLatitude" v-model="latitude" type="number" min="-90" max="90" step="any" required /></div><div><label for="nearbyRadius">搜索半径（米）</label><input id="nearbyRadius" v-model.number="radius" type="number" min="1" :max="capability?.maxRadiusMeters" required /></div><div><label for="nearbyCategory">商家类型</label><select id="nearbyCategory" v-model="category"><option value="">全部</option><option v-for="value in categoryOptions" :key="value" :value="value">{{ categoryLabels[value] ?? value }}</option></select></div></div><button :disabled="busy">查询附近商家</button></form><p v-if="message" role="status">{{ message }}</p><AmapView :longitude="longitude" :latitude="latitude" :points="result?.items" /><template v-if="result"><article v-for="m in result.items" :key="m.id" class="workspace-card"><h2>{{ m.name }}</h2><p>{{ m.address }}</p><p>直线距离 {{ m.distanceMeters }} 米</p></article><p v-if="!result.items.length">附近暂无已设置有效位置的公开商家。</p><PaginationBar :page="result.page" :size="20" :total="result.total" :disabled="busy" @change="search" /></template></section></template>
